package com.example.app09.application.service; import com.example.app09.domain.entity.Post; import com.example.app09.infrastructure.repository.PostRepository; import java.util.List; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service public class PostService { private final PostRepository repository; public PostService(PostRepository repository) { this.repository=repository; } @Transactional(readOnly=true) public List<Post> list() { return repository.findAll(); } @Transactional public Post create(Post e) { return repository.save(e); } }
